import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_N": n},
        )
        for n in [32, 64, 128, 256, 512, 1024, 2048, 4096]
    ],
    key=["N"],
)
@triton.jit
def _softmax_kernel(
    inp_ptr,
    out_ptr,
    M,
    N,
    stride_im,
    stride_in,
    stride_om,
    stride_on,
    BLOCK_N: tl.constexpr,
):
    pid_m = tl.program_id(0)
    row_inp = inp_ptr + pid_m * stride_im
    row_out = out_ptr + pid_m * stride_om

    LOG2E: tl.constexpr = 1.4426950408889634

    # Pass 1: Online max + sum_exp
    row_max = -float("inf")
    row_sum = 0.0
    for start in range(0, N, BLOCK_N):
        offs = start + tl.arange(0, BLOCK_N)
        mask = offs < N
        x = tl.load(row_inp + offs * stride_in, mask=mask, other=-float("inf"))
        block_max = tl.max(x, axis=0)
        new_max = tl.maximum(row_max, block_max)
        row_sum = row_sum * tl.math.exp2((row_max - new_max) * LOG2E) + tl.sum(
            tl.math.exp2((x - new_max) * LOG2E), axis=0
        )
        row_max = new_max

    inv_sum = 1.0 / row_sum

    # Pass 2: normalize and store
    for start in range(0, N, BLOCK_N):
        offs = start + tl.arange(0, BLOCK_N)
        mask = offs < N
        x = tl.load(row_inp + offs * stride_in, mask=mask, other=-float("inf"))
        e = tl.math.exp2((x - row_max) * LOG2E)
        y = (e * inv_sum).to(tl.bfloat16)
        tl.store(row_out + offs * stride_on, y, mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        M, N = x.shape
        out = torch.empty_like(x)

        grid = (M,)
        _softmax_kernel[grid](
            x,
            out,
            M,
            N,
            x.stride(0),
            x.stride(1),
            out.stride(0),
            out.stride(1),
        )
        return out


